package com.example.security

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [36])
class LicenseVerificationTest {

    private val masterPublicKeyHex = "7fa8b86c9a372f2304e2b9bfd56b72299fced510e070e2a66b0a50b4487c3dec"

    // Real signed license generated by issue-license.js using the authority private key
    private val validLicenseKey = "GTM6-"

    @Test
    fun testParseLicenseKey() {
        val cert = LicenseManager.parseLicenseKey(validLicenseKey)
        assertNotNull(cert)
        cert!!
        assertEquals("Ed25519", cert.header.alg)
        assertEquals("GrainTradeManager", cert.payload.app)
        assertEquals("GTM-ABCD-1234-EF56-7890", cert.payload.machineId)
        assertEquals("شركة السلام للتجارة", cert.payload.clientName)
        assertEquals("Enterprise", cert.payload.tier)
    }

    @Test
    fun testCryptographicSignatureVerification() {
        val cert = LicenseManager.parseLicenseKey(validLicenseKey)!!
        val canonical = cert.payload.toCanonicalString()
        val pubKeyBytes = hexToByteArray(masterPublicKeyHex)
        val sigBytes = hexToByteArray(cert.signatureHex)

        val isValid = Ed25519Verifier.verify(
            publicKeyBytes = pubKeyBytes,
            messageBytes = canonical.toByteArray(Charsets.UTF_8),
            signatureBytes = sigBytes
        )
        assertTrue("Signature must be mathematically valid with Ed25519 master key", isValid)
    }

    @Test
    fun testTamperedPayloadFailsVerification() {
        val cert = LicenseManager.parseLicenseKey(validLicenseKey)!!
        val tamperedPayload = cert.payload.copy(clientName = "قرصان غير مصرح به")
        val canonical = tamperedPayload.toCanonicalString()
        val pubKeyBytes = hexToByteArray(masterPublicKeyHex)
        val sigBytes = hexToByteArray(cert.signatureHex)

        val isValid = Ed25519Verifier.verify(
            publicKeyBytes = pubKeyBytes,
            messageBytes = canonical.toByteArray(Charsets.UTF_8),
            signatureBytes = sigBytes
        )
        assertFalse("Tampered payload must fail cryptographic verification", isValid)
    }

    @Test
    fun testHardwareIdMatching() {
        assertTrue(HardwareIdProvider.isMatchingDevice("GTM-1234-5678-90AB-CDEF", "GTM-1234-5678-90AB-CDEF"))
        assertTrue(HardwareIdProvider.isMatchingDevice("US-1234-5678-90AB-CDEF", "GTM-1234-5678-90AB-CDEF"))
        assertTrue(HardwareIdProvider.isMatchingDevice("GTM-1234-5678-90AB-CDEF", "US-1234-5678-90AB-CDEF"))
        assertFalse(HardwareIdProvider.isMatchingDevice("GTM-1234-5678-90AB-CDEF", "GTM-9999-5678-90AB-CDEF"))
    }

    private fun hexToByteArray(hex: String): ByteArray {
        val len = hex.length
        val data = ByteArray(len / 2)
        var i = 0
        while (i < len) {
            data[i / 2] = ((Character.digit(hex[i], 16) shl 4) +
                Character.digit(hex[i + 1], 16)).toByte()
            i += 2
        }
        return data
    }
}
